package ar.org.inclusoft.api.attendance;
import java.util.*; import jakarta.persistence.*; import org.hibernate.annotations.UuidGenerator;
@Entity @Table(name="attendance_entries") class AttendanceEntry { @Id @UuidGenerator private UUID id; @ManyToOne(optional=false) @JoinColumn(name="session_id") private AttendanceSession session; @Enumerated(EnumType.STRING) @Column(name="participant_type",nullable=false) private AttendanceParticipantType participantType; @Column(name="participant_id",nullable=false) private UUID participantId; @Column(name="participant_name",nullable=false,length=160) private String participantName; @Enumerated(EnumType.STRING) @Column(name="attendance_status",nullable=false) private AttendanceStatus attendanceStatus; @Column(length=500) private String observation; protected AttendanceEntry(){} AttendanceEntry(AttendanceParticipantType t,UUID id,String name,AttendanceStatus status,String obs){participantType=t;participantId=id;participantName=name;attendanceStatus=status;observation=obs;} void assignTo(AttendanceSession value){session=value;} AttendanceParticipantType getParticipantType(){return participantType;} UUID getParticipantId(){return participantId;} String getParticipantName(){return participantName;} AttendanceStatus getAttendanceStatus(){return attendanceStatus;} String getObservation(){return observation;} }
